/// Pulls the `d="..."` values out of the SVG literal keyed by [id].
List<String> pathsFor(String source, String id) {
  final keyAt = source.indexOf("'$id':");
  expect(keyAt, isNot(-1), reason: 'no SVG entry for $id');
  const fence = "'''";
  final open = source.indexOf(fence, keyAt);
  final close = source.indexOf(fence, open + 3);
  return RegExp(
    r'd="([^"]+)"',
  ).allMatches(source.substring(open, close)).map((m) => m.group(1)!).toList();
}

void main() {
  test('forge icons carry the frozen path data', () {
    final source = File('lib/core/forge.dart').readAsStringSync();
    for (final id in const [
      'github',
      'gitlab',
      'gitea',
      'forgejo',
      'codeberg',
    ]) {
      expect(
        pathsFor(source, id),
        frozenIconPaths[id],
        reason: '$id drifted from the frozen upstream path data',
      );
    }
  });

  test('provider icons carry the frozen path data', () {
    final source = File('lib/widgets/provider_icon.dart').readAsStringSync();
    for (final id in const [
      'claude',
      'codex',
      'copilot',
      'minimax',
      'omp',
      'opencode',
      'pi',
    ]) {
      expect(
        pathsFor(source, id),
        frozenIconPaths[id],
        reason: '$id drifted from the frozen upstream path data',
      );
    }
  });
}
